import java.util.*;
public class GeneticEngineering {

	public static void main(String[] args) {

		Scanner sc=new Scanner(System.in);
		String str=sc.next();

		int insert=0;

		if(str.length()>0) {
			int count=1;
			for(int i=1;i<str.length();i++)
			{
				if(str.charAt(i)==str.charAt(i-1))
				{
					count++;
				}
				else
				{
					if(count%2==0)
					{
						insert++;
					}
					count=1;
				}
			}
			if(count%2==0)
			{
				insert++;
			}
		}
		System.out.println(insert);

	}

}
